GimCorpus.put(458,0,[[1,1,"המדברות וכו'. א\"א דוקא לאותו השבט עכ\"ל:",1,0],[1,3,"הרי זה גזלן. א\"א להוציאו בדיינין. עכ\"ל:",1,0],[1,4,"ואין לבעל המצודה. א\"א ואיך לא חילק בין צבי רץ כדרכו וגוזלין מפריחים לשאינן כן והלא המשנה חילקה בהן עכ\"ל:",1,0],[1,11,"ברשות שבת וכו'. א\"א יש כאן ערבובי דברים שאין הגמרא הולכת ע\"ז הדרך ואין בגמרא שיהא פיסלא חולק בנכסי הגר אלא בפאה ובשבת ובטומאה ובגיטין כי כן דרך הגמרא ומפרש בגמרא מה טיבן של הפסקות עכ\"ל:",1,0],[1,13,"בקעה גדולה כו'. א\"א אינו כן שכבר אמרו בגמרא כל שנקראת על שמו ה\"ד דאמרי בי גרגותא דפלניא פר\"ח ז\"ל שדה בית השלחין ששותה מגרגותא חדא עכ\"ל:",1,0],[2,2,"כמו שביארנו וכו'. א\"א כל זה הולך על דרך שכתב למעלה בהל' מכירה פ\"א ואינו נכון בעיני עכ\"ל:",1,0],[3,5,"אמר לו חלק כך וכו'. א\"א זה הדרך הולך על דרך פירוש הרב ז\"ל שפירש במסכת גיטין וקשיא לן מה שאמרו במנחות בית בביתי אני מוכר לך מראהו עלייה הגרועה ואם נפלה נפלה ללוקח וכן שור בשורי אמאי והא לא סיים והא לא קנה כלום. ואולי נאמר כיון שהדין ידוע שיד בעל השטר על התחתונה כאילו פירש הגרוע או הנפול או המת ודין זה כשאין שם אלא גרוע אחד או מת אחד שהוא כמסויים אבל אם היו שנים גרועים או שנים מתים לדעת הרב ז\"ל לא קנה כלום עכ\"ל:",1,0],[3,8,"ואין לדבר זה ראיה וכו'. א\"א אע\"פ שאין ראיה לדבר זכר לדבר וטעם גדול יש לדבר ואיך יתכן דזה מוכר קרקע או נותנו ואומר איני נותנו או מוכרו אא\"כ יעשה לי כך וכך ונוציא אותו מידו ולא עשה בו מה שהתנה עליו אבל גיטין וקדושין אומדן דעתא הוא מכיון שנתן דעתו לגרש או לקדש אינו אלא כמפליג בדברים וקירוב הדעת וריחוק הדעת אין תנאי מועיל בו לרחק ולקרב אא\"כ חזקו בכפילו ובכל העניינים שנתפרשו בו כי כולם חזוק התנאי הם ובין תבין ונחלת בני גד ובני ראובן לא היתה מוחזקת ביד ישראל ואינו דומה לקרקע המוחזק לו לאדם מירושתו או ממקחו עכ\"ל:",1,0],[4,1,"לא אמר כלום וכו'. א\"א דוקא אמר הרי היא בטילה אבל אמר בטילה היא אינה מתנה והכין איתא בגיטין ובכריתות עכ\"ל:",1,0],[4,4,"ראובן שרצה ליתן וכו'. א\"א דוקא מתנה אבל פריעת חוב אינו יכול לחזור בו וכן בפקדון אם הוחזק הנפקד כפרן עכ\"ל:",1,0],[4,9,"וקטנה תזכה וכו'. א\"א אין דבר זה מחוור במתנה אלא במציאה עכ\"ל:",1,0],[4,10,"לא קנה וכו'. א\"א הוא הדין אם אמר להם תנו צריכין הם לכותבו עכ\"ל:",1,0],[4,13,"ותחזור לבעליה וכו'. א\"א רעיון רוח ונשבע שבועת היסת עכ\"ל:",1,0],[5,1,"ממון אחרים וכו'. א\"א פירוש הטובה שקבל מזה עכ\"ל:",1,0],[5,4,"מודעה לה וכו'. א\"א כגון המעשה שהוא מביא עכ\"ל:",1,0],[6,17,"ודברים אלו וכו' עד שיטרוף בהן. א\"א דבריו מעורבים כי נראה מדבריו שהוא מפרש ניתנו להכתב או לא ניתנו אם צריכין ליכתב לגבות ממשועבדין או אין צריכין ליכתב ואח\"כ אמר לפיכך אינו כשטר שיטרוף בהן וכיון שפשט שלא ניתנו ליכתב הרי הוא טורף בהם. ואולי הוא מפרש ניתנו ליכתב ולא נתן אם יש להם דין שט\"ח או לא ואין דעות כל המפרשים שוות בזה עכ\"ל:",1,0],[6,21,"השולח וכו' עד חוץ מן המאכל וכו'. א\"א תמה אני מועטין ואכל למה הדרי בב\"ד ואי בשהן קיימין היא בעיא ולא איפשיטא הלכך אין נגבין בב\"ד אלא אם תפס לא מפקינן מיניה חוץ מייבא וסבתכא ואם אכלתו לא הדרי ואפילו תפס מפקינן מיניה:",1,0],[6,24,"הורו רבותי שאם היה מנהג וכו' עד נשבע ונוטל. א\"א איני משוה עם רבותיו בזה וזאת הגרמה דומה לזרעוני גנה ולא צמחו שאינו משלם לו (אלא) ההוצאה. וכללו של דבר אבוד ממון שבעל הממון עושה אותו אע\"פ שגרם לו זה פטור עכ\"ל:",1,0],[7,7,"וכמה מנכין וכו' עד ומשלם לו השאר. א\"א לא ראיתי חשיבות עם צרות עין:",1,0],[7,9,"מת שמעון קודם שנשא אשה עד אין היורשים משלמים כלום. א\"א מעולם לא ראיתי בגמרא מנהג לשושבינות אלא לסבלונות:",1,0],[7,14,"השולח תשורה לחבירו עד שיפרש שהוא מלוה וכן השולח לחבירו כדי יין וכדי שמן וכו' עד אלא במעות בלבד. א\"א דבר זה אינו מחוור:",1,0],[8,12,"שכ\"מ שאמר כתבו ותנו לפלוני מנה עד כותבין ונותנין לאחר מיתה וכו'. א\"א אני וחבירי אומרים ואפילו כתבו מחיים [לפי שהעדים] שלוחים הם וכיון שהשולח מת מעשה השליחות בטל שהרי לא נתקיים מעשה השליח אפי' שעה אחת מחיים:",1,0],[8,14,"שכ\"מ שכתב כל נכסיו מתנה סתם וכו' עד במתנת בריא וכו'. א\"א ואם שייר צריכה קנין כי בלא קנין אינה כלום. עכ\"ל:",1,0],[8,17,"אבל אם נתן לו המקצת בפירוש במתנת שכ\"מ וכו' עד קנה זה המקצת. א\"א זהו המצוה מחמת מיתה. עכ\"ל:",1,0],[8,21,"שכיב מרע שכתב כל נכסיו וכו' עד ואם כנמלך אחר ששייר וכו' מת קנו כולן וכו' עד כל נכסיו הנשארים. א\"א האחרון צריך שיהא קניינו לייפות כחו:",1,0],[9,6,"מי שאמרו לו בשעת מיתתו וכו' עד משום מתנה. א\"א פירושה וירושה אין לה הפסק ואפילו אמר בלשון מתנה כרבי יוחנן בן ברוקא עכ\"ל:",1,0],[9,7,"גר שיש לו בן וכו' עד מתנתו קיימת. א\"א כן אמר הגאון ואין הדעת נוחה הימנו ויש לומר דעת אחרת טובה מזו עכ\"ל:",1,0],[10,2,"לפיכך היורש עדיין שטר זה וכו' ומתנת שכיב מרע וכו' עד ולפיכך אינו מוחל. א\"א יש כאן שיבושים והגהתי אותם מדעתי וכבר פירש הרב ז\"ל הטעם פ' הכותב שדברי שכ\"מ ככתובים וכמסורין דמו שחכמים עשאוה כשל תורה כמי שקבל המתנה והטעם שכתוב כאן הוא יותר טוב ומספיק ממ\"ש הרב ז\"ל. עכ\"ל:",1,0],[10,10,"אמר מנה לפלוני בידי וכו' עד שחייבין ליתן. א\"א בחיי ראשי טעות גדול טעה בזה ובשביל שראה בגמרא אדרבא איפכא מסתברא כתב את כל זה וחס ושלום שלא נתכוונו לכך אלא כמי שאומר אם שמעת חילוק בזה א\"א כך אלא כך ולעולם בין בזה ובין בזה נאמנים שאם הודה כמערים שלא להשביע את בניו הרי שאין חייבין ליתן ואם כמודה איך נאמר מנין היו יודעין שהן חייבים ליתן הרי יודעין ומצווים וכשאמרו עשינו מצות אבינו נאמנין ותו לא מידי. ועוד י\"ל כי מה שהקשו בגמרא אדרבא איפכא מסתברא על דין אמת הקשו דמנה לפלוני בידי הודאה היא וכדברי בריא הוא ואם נכתב כמלוה בשטר הוא ויש בה פנים שלא יהו נאמנים לומר פרענו אבל תנו שהוא לשון מתנה אם לא אמר כתובו אע\"פ שכתבו העדים ונתנו לו יכולין לומר פרענו וזהו איפכא מסתברא. מיהו כל זמן שלא נכתבה ונמסרה שטר ההודאה נאמנים לומר פרענו ואף בחיוב ב\"ד כן. עכ\"ל:",1,0],[11,6,"אמר לפלוני ופלוני ובני פלוני עד מחצה. א\"א לא נתברר לי דבר זה אם יאמר יהיה נכסי לראובן ושמעון ובני לוי למה לא יהיו בני לוי בשליש הנכסים כאילו אמר לראובן שמעון ולוי ואם אמר לראובן ולשמעון ולבני לוי כמו כן בשליש. אבל אם אמר לראובן ושמעון ולבני לוי אפשר שיהיה כדבריו לפי שנתן ראובן ושמעון בכלל אחד ובני לוי בכלל אחד:",1,0],[11,7,"שכיב מרע שאמר יחלוק פלוני בנכסי כו'. א\"א הרב ז\"ל כתב כן ועיקר:",1,0],[12,6,"שכ\"מ שאמר נכסי וכו' עד מספיק להן. א\"א כל מ\"ש בכאן לא כתב אלא להזהר מן הקושיא ממה ששלח רב אחא עם ברייתא זו של תנו שקל לבני בכל שבת כו' ולא היה צריך לזה וגם זה הטעם אינו מוטעם ויש לנו טעם יפה. עכ\"ל:",1,0],[12,7,"נכסי לפלוני ואחריו לפלוני וכו' עד לא עשה ולא כלום. א\"א זה אינו מחוור המעשה דרב ביבי בר אביי דאקנייה לבנו הקטן ולא תפסו עליו אלא משום דאחריו דרב ביבי היא עצמה היתה אבל משום שהקנה לבנו לא תפסו עליו. ועוד כי הדרך שכתב אינו אלא כדברי ר\"י בן ברוקא והוא כתב שאינו בבריא. ואני סבור שהוא מפרש אותו ענין דרב ביבי כדרך שכתב בכאן אימר דאמר רשב\"ג שנתן לאחר אבל לעצמו כגון שנתן לבנו קטן שהוא אוכל הפירות מי אמר ואם כך הוא מפרש נותן לבנו גדול מנין לו שלא הועיל כי אם לדעת ר\"י בן ברוקא והוא אמר שלא אמר ר\"י בן ברוקא בבריא עכ\"ל:",1,0]]);
